// ─────────────────────────────────────────────────────────────────────────────
//  HodReviewScorecard.tsx  — pure UI, zero SP calls
//  All logic in useHodReview hook.
// ─────────────────────────────────────────────────────────────────────────────

import * as React from "react";
import styles from "./HodReviewScorecard.module.scss";
import { useHodReview } from "../../../hooks/useHodReview";

interface HodReviewScorecardProps {
  candidateId:  number;
  employeeList: any[];
  onBack:       () => void;
}

// ── Reusable left-panel field ─────────────────────────────────────────────────
const InfoField: React.FC<{
  icon: React.ReactNode;
  label: string;
  value: string | number;
}> = ({ icon, label, value }) => (
  <div className={styles.infoField}>
    <div className={styles.infoLabel}>{icon} {label}</div>
    <div className={styles.infoValue}>{value || "—"}</div>
  </div>
);

// ── Decision card ─────────────────────────────────────────────────────────────
const DecisionCard: React.FC<{
  variant: "select" | "reject" | "hold";
  label:   string;
  icon:    React.ReactNode;
  active:  boolean;
  onClick: () => void;
}> = ({ variant, label, icon, active, onClick }) => (
  <button
    type="button"
    className={[
      styles.decCard,
      styles[`decCard_${variant}`],
      active ? styles[`decCard_${variant}_on`] : "",
    ].filter(Boolean).join(" ")}
    onClick={onClick}
  >
    <span className={styles.decCardIcon}>{icon}</span>
    <span className={styles.decCardLabel}>{label}</span>
  </button>
);

// ── SVG icons ─────────────────────────────────────────────────────────────────
const I = {
  user:  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>,
  close: <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>,
  chev:  <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round"><polyline points="9 18 15 12 9 6"/></svg>,
  gen:   <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><circle cx="12" cy="8" r="4"/><path d="M6 20v-2a6 6 0 0 1 12 0v2"/></svg>,
  book:  <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>,
  wave:  <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>,
  cal:   <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>,
  grid:  <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/></svg>,
  warn:  <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/></svg>,
  info:  <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/></svg>,
  panel: <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>,
  check: <svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="#22c55e" strokeWidth="2.2" strokeLinecap="round"><circle cx="12" cy="12" r="10"/><polyline points="9 12 11 14 15 10"/></svg>,
  cross: <svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="#ef4444" strokeWidth="2.2" strokeLinecap="round"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>,
  hold:  <svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="#f59e0b" strokeWidth="2.2" strokeLinecap="round"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>,
  ok:    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><circle cx="12" cy="12" r="10"/><polyline points="9 12 11 14 15 10"/></svg>,
};

// ─────────────────────────────────────────────────────────────────────────────

const HodReviewScorecard: React.FC<HodReviewScorecardProps> = ({
  candidateId, employeeList, onBack,
}) => {
  const {
    decision, handleSetDecision,
    comments, handleSetComments,
    commentsError, decisionError,
    submitting, alertMsg, alertType,
    handleSubmit, hideAlert,
  } = useHodReview(candidateId, employeeList, onBack);

  return (
    <div className={styles.overlay}>
      <div className={styles.modal}>

        {/* Alert */}
        {alertMsg && (
          <div className={[styles.alert, alertType === "error" ? styles.alertErr : styles.alertOk].join(" ")}>
            <span>{alertMsg}</span>
            <button className={styles.alertClose} onClick={hideAlert}>{I.close}</button>
          </div>
        )}

        {/* Header */}
        <div className={styles.header}>
          <div className={styles.headerLeft}>
            <div className={styles.avatar}>{I.user}</div>
            <div>
              <div className={styles.breadcrumb}>
                <span>CANDIDATE SELECTION</span>
                <span className={styles.bChev}>{I.chev}</span>
                <span className={styles.bActive}>EVALUATION PREVIEW</span>
              </div>
              <h1 className={styles.title}>Candidate Evaluation Review</h1>
            </div>
          </div>
          <button className={styles.closeBtn} onClick={onBack}>{I.close}</button>
        </div>

        {/* Body */}
        <div className={styles.body}>

          {/* ── Right panel ── */}
          <main className={styles.rightPanel}>
            <div className={styles.panelScroll}>
              <div className={styles.decSection}>

                <div className={styles.decHeader}>
                  <span className={styles.lightning}>⚡</span>
                  <div>
                    <h2 className={styles.decTitle}>Do you wish to select this candidate?</h2>
                    <p className={styles.decSub}>As HOD, please review the evaluation above and provide your final decision.</p>
                  </div>
                </div>

                {/* 3 decision cards */}
                <div className={[styles.decGrid, decisionError ? styles.decGridErr : ""].filter(Boolean).join(" ")}>
                  <DecisionCard variant="select" label="YES, SELECT" icon={I.check} active={decision === "select"} onClick={() => handleSetDecision("select")} />
                  <DecisionCard variant="reject" label="NO, REJECT"  icon={I.cross} active={decision === "reject"} onClick={() => handleSetDecision("reject")} />
                  <DecisionCard variant="hold"   label="ON HOLD"     icon={I.hold}  active={decision === "hold"}   onClick={() => handleSetDecision("hold")}   />
                </div>
                {decisionError && <p className={styles.errMsg}>Please select a decision.</p>}

                {/* Comments */}
                <div className={styles.commentsWrap}>
                  <label className={[styles.commentsLabel, commentsError ? styles.commentsLabelErr : ""].filter(Boolean).join(" ")}>
                    HOD DECISION JUSTIFICATION / COMMENTS <span className={styles.req}>*</span>
                    {commentsError && <span className={styles.errInline}> — Required</span>}
                  </label>
                  <textarea
                    className={[styles.commentsArea, commentsError ? styles.commentsAreaErr : ""].filter(Boolean).join(" ")}
                    rows={5}
                    placeholder="Provide your final decision rationale…"
                    value={comments}
                    onChange={(e) => handleSetComments(e.target.value)}
                  />
                </div>

              </div>
            </div>
          </main>

        </div>

        {/* Footer */}
        <div className={styles.footer}>
          <button className={styles.cancelBtn} onClick={onBack} disabled={submitting} type="button">
            CANCEL
          </button>
          <button
            className={[styles.submitBtn, !decision ? styles.submitOff : ""].filter(Boolean).join(" ")}
            onClick={handleSubmit}
            disabled={submitting || !decision}
            type="button"
          >
            {submitting
              ? <><span className={styles.btnSpinner} /> SUBMITTING…</>
              : <>{I.ok} SUBMIT ACTION</>
            }
          </button>
        </div>

      </div>
    </div>
  );
};

export default HodReviewScorecard;
